/* Confirm recommendations by day; publish them together when leaving the chat. */
(()=>{
 const pending=new Map();let modal=null,returnFocus=null,committing=false;
 const style=document.createElement('style');style.textContent=`
 .outfit{position:relative}.outfit.look-selected{border:2px solid #b45350!important;box-shadow:inset 0 0 0 2px #b4535020}.look-check{position:absolute;z-index:2;top:8px;right:8px;width:33px;height:33px;border:2px solid #b45350;border-radius:50%;background:#fffaf4;color:#b45350;display:grid;place-items:center;padding:0;line-height:1;appearance:none;box-shadow:0 0 0 2px #fffaf4}.look-check svg{display:block;width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}.look-check[aria-pressed=true]{background:#b45350;color:#fff}.look-status{display:block;font-size:13px;color:#b45350;text-align:center;padding:7px 4px;font-weight:600}.generation-carousel .look-check{top:8px}.generation-carousel .look-status{order:3}.card-save{width:calc(100% - 10px);margin:12px 5px 0;padding:10px;border-radius:24px;border:1px solid #e1cfbc;background:#f2e9dc;color:#81674f}.chat-finish{display:block;width:100%;border:0;background:none;padding:7px 4px 0;color:#8d5148;font-size:12px}.look-dialog{position:absolute;inset:0;z-index:20;background:#30201966;display:flex;align-items:center;justify-content:center;padding:20px 14px}.look-dialog-sheet{background:#faf7f1;border:1px solid #e8dfd5;border-radius:24px;padding:15px;width:100%;max-height:92%;overflow:auto;box-shadow:0 15px 45px #30201930}.look-dialog-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.look-dialog h2{font-size:17px;margin:0}.look-dialog-close{border:0;background:none;font-size:25px;min-width:32px;min-height:32px}.look-preview{border:1px solid #e8dfd5;border-radius:18px;padding:10px;background:#fffcf8}.look-preview strong{font-size:16px}.look-preview time{font-size:12px;color:#8d8b87;float:right;margin-top:3px}.look-preview img{display:block;width:100%;max-height:37vh;object-fit:contain;border-radius:14px;margin:12px 0;background:#f0e9e1}.look-preview h3{font-size:15px;margin:9px 0 4px}.look-preview p{font-size:12px;color:#8d8b87;margin:0;line-height:1.6}.look-day-label{display:block;font-size:14px;margin:14px 0 7px}.look-day{width:100%;padding:10px;border:1px solid #ddcbbc;border-radius:10px;background:#fffaf4;font:inherit;color:#503a2b}.look-apply{width:100%;border:1px solid #dfcbb6;background:#f2e8da;border-radius:24px;padding:12px;color:#81674f;margin-top:12px;font:inherit}.look-note{font-size:12px;line-height:1.6;color:#88786b;margin:8px 0 0}.look-dialog :focus-visible{outline:2px solid #b45350;outline-offset:2px}
 `;document.head.append(style);
 const finish=document.createElement('button');finish.type='button';finish.className='chat-finish';document.querySelector('.composer-wrap').append(finish);
 const key=o=>o.id+':'+o.image;
 function assigned(k){return [...pending].filter(([,o])=>key(o)===k).map(([day])=>day)}
 function refresh(){document.querySelectorAll('.outfit[data-look-id]').forEach(card=>{let check=card.querySelector('.look-check'),status=card.querySelector('.look-status');if(!check){check=document.createElement('button');check.type='button';check.className='look-check';card.append(check);status=document.createElement('span');status.className='look-status';card.append(status)}const days=assigned(card.dataset.lookId+':'+card.dataset.lookImage),selected=days.length>0;card.classList.toggle('look-selected',selected);check.setAttribute('aria-pressed',String(selected));check.setAttribute('aria-label',(selected?'取消选择':'选择穿搭')+'：'+card.querySelector('h3').textContent);check.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+(selected?'M5 12l4.5 4.5L19 7':'M12 5v14M5 12h14')+'"/></svg>';status.textContent=selected?'已勾选 ✓ · 第 '+days.join('、')+' 天':'选择这套穿搭';const save=card.querySelector('[data-save-look]');if(save)save.textContent=selected?'修改应用天数':'选择并应用'});finish.textContent=pending.size?'结束对话并同步（'+pending.size+' 天）':'结束对话并返回首页'}
 const observer=new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('.outfit')||n.querySelector?.('.outfit')))))refresh()});observer.observe(document.querySelector('.screen'),{childList:true,subtree:true});refresh();
 function dismiss(){if(!modal)return;modal.remove();modal=null;for(const el of document.querySelector('.screen').children)el.inert=false;returnFocus?.focus({preventScroll:true})}
 function open(card,button){returnFocus=button;const id=Number(card.dataset.lookId),image=card.dataset.lookImage,name=card.querySelector('h3').textContent,description=card.querySelector('p').textContent,days=assigned(id+':'+image);modal=document.createElement('div');modal.className='look-dialog';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label','确认应用穿搭');modal.innerHTML=`<section class="look-dialog-sheet"><div class="look-dialog-head"><h2>将这套穿搭应用到哪一天？</h2><button type="button" class="look-dialog-close" aria-label="取消应用">×</button></div><article class="look-preview"><strong></strong><time></time><img alt=""><h3></h3><p></p></article><label class="look-day-label" for="look-day">选择应用日期</label><select class="look-day" id="look-day"></select><button class="look-apply" type="button"></button><p class="look-note" role="status"></p></section>`;modal.querySelector('img').src='assets/'+image+'.jpg';modal.querySelector('img').alt=name;modal.querySelector('h3').textContent=name;modal.querySelector('.look-preview p').textContent=description;const select=modal.querySelector('select');for(let day=1;day<=chatTrip.days;day++){const opt=document.createElement('option');opt.value=day;opt.textContent='第 '+day+' 天 · '+chatDayDate(day).label;select.append(opt)}select.value=String(days[0]||Number(card.dataset.displayDay)||id);const apply=modal.querySelector('.look-apply');function update(){const day=Number(select.value);modal.querySelector('strong').textContent='第'+day+'天 · '+card.querySelector('.card-head strong').textContent.split(' · ').slice(1).join(' · ');modal.querySelector('time').textContent=chatDayDate(day).label;apply.textContent='应用到第 '+day+' 天';modal.querySelector('.look-note').textContent=(pending.has(day)?'该日期已有待同步搭配，确认后将替换。':'确认后可继续聊天。')+'结束对话时自动同步到首页。'}select.onchange=update;update();apply.onclick=()=>{pending.set(Number(select.value),{id,image});dismiss();refresh();showToast('已勾选，将在结束对话后同步到第 '+select.value+' 天')};modal.querySelector('.look-dialog-close').onclick=dismiss;modal.onclick=e=>{if(e.target===modal)dismiss()};modal.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();dismiss()}if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,select')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}};const screen=document.querySelector('.screen');for(const el of screen.children)el.inert=true;screen.append(modal);select.focus()}
 document.addEventListener('click',event=>{const button=event.target.closest('.look-check,[data-save-look]');if(!button)return;const card=button.closest('.outfit');if(!card)return;if(button.classList.contains('look-check')&&button.getAttribute('aria-pressed')==='true'){for(const day of assigned(card.dataset.lookId+':'+card.dataset.lookImage))pending.delete(day);refresh();showToast('已取消勾选');return}open(card,button)});
 function end(){if(committing||modal)return;committing=true;finish.disabled=true;window.parent.postMessage({type:'ootrip:chat-finish',looks:[...pending].map(([day,o])=>({day,image:o.image}))},location.origin);}
 finish.onclick=end;window.onBack=end;
 window.addEventListener('message',e=>{if(e.source!==window.parent||e.origin!==location.origin||e.data?.type!=='ootrip:chat-sync-error')return;committing=false;finish.disabled=false;showToast(e.data.message||'同步失败，请重试')});
})();
